#pragma once

#include <stddef.h>
#include <stdint.h>

// Short PCM sounds stored in flash (16 kHz, mono, 16-bit), generated by
// firmware/tools/gen_sounds.py.

#define SOUND_SAMPLE_RATE_HZ 16000

typedef enum {
    SOUND_TOUCH = 0,
    SOUND_CONFIRM,
    SOUND_ALERT,
    SOUND_STUDY_DONE,
    SOUND_COUNT,
} sound_id_t;

typedef struct {
    const int16_t *samples;
    size_t count;
} sound_pcm_t;

extern const sound_pcm_t sound_pcm_table[SOUND_COUNT];
